// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MONEY_BOX c;
    Log log_;

    function setUp() public {
        c = new MONEY_BOX();
        log_ = new Log();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log_));
        amount = bound(amount, 1, type(uint256).max / 2);
        c.SetLogFile(address(log_));
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);
        (address sndr, , uint256 val, ) = log_.History(0);
        assertTrue(sndr == actor && val == amount);
    }
}
